@startuml

class OilCompany {}

class GasStation {
  + location : string
}

class Pump {
  + gasolineType : string
  + currentLevel : float
  + reorderingLevel : float
  + criticalLevel : float
  + isBlocked : boolean
  + isAvailable : boolean
  + getDailyReport()
}

class Reservoir {
  + quantity : float
}

class Customer {
  + name : string
  + isSuspended : boolean
  + isBlocked : boolean
  + slack : int
}

class CreditCard {
  + cardNumber : string
  + isBlocked : boolean
}

class RefuelTurn {
  + amount : float
  + timestamp : datetime
}

class Invoice {
  + month : int
  + year : int
  + discount : float
  + totalAmount : float
  + status : string
}

class Payment {
  + amount : float
  + date : date
}

GasStation "1" -- "*" Pump : possesses
Pump "1" *-- "1" Reservoir
Pump "0..1" -- "0..1" Customer : used by
Pump "0..1" -- "0..1" RefuelTurn : records

Customer "1" -- "0..*" RefuelTurn : performs
Customer "1" -- "0..*" CreditCard : owns
Customer "1" -- "0..*" Invoice : receives
Invoice "1" -- "0..*" Payment : settled by
Invoice "1" -- "1..*" RefuelTurn : contains

@enduml

